-- =====================================================
-- OPAC CATALOG: Library Inventory 2026 (For OPAC)
-- Run this whole script once in the Supabase SQL Editor.
-- Safe to re-run: a book whose accession number already exists is updated, not duplicated.
-- Only the columns below are changed; date received, pages, source of fund, price and remarks stay as they are.
-- 1502 copies of 549 titles.
-- =====================================================

BEGIN;

-- OPAC fields. Every copy of a title shares one book_id; the kiosk works out "available / on loan" from borrow_records.
ALTER TABLE books
  ADD COLUMN IF NOT EXISTS book_id VARCHAR(20),
  ADD COLUMN IF NOT EXISTS subject TEXT,
  ADD COLUMN IF NOT EXISTS copy_no VARCHAR(10),
  ADD COLUMN IF NOT EXISTS loan_policy VARCHAR(50), -- Library use only / Library & classroom use / Library & home use
  ADD COLUMN IF NOT EXISTS ddc_no VARCHAR(100),
  ADD COLUMN IF NOT EXISTS volumes VARCHAR(100),
  ADD COLUMN IF NOT EXISTS publisher VARCHAR(255);

CREATE INDEX IF NOT EXISTS idx_books_book_id ON books(book_id);

ON CONFLICT (accession_number) DO UPDATE SET
  book_id = EXCLUDED.book_id,
  title = EXCLUDED.title,
  author = COALESCE(NULLIF(EXCLUDED.author, ''), b.author),
  publisher = COALESCE(EXCLUDED.publisher, b.publisher),
  copyright_year = COALESCE(EXCLUDED.copyright_year, b.copyright_year),
  isbn = COALESCE(EXCLUDED.isbn, b.isbn),
  subject = EXCLUDED.subject,
  ddc_no = EXCLUDED.ddc_no,
  call_number = EXCLUDED.call_number,
  category = EXCLUDED.category,
  volumes = COALESCE(EXCLUDED.volumes, b.volumes),
  copy_no = EXCLUDED.copy_no,
  loan_policy = EXCLUDED.loan_policy,
  updated_at = NOW();

COMMIT;
